import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry function-valued definitions', () => {
  it('validates a function-valued definition against the schema returned for that call', async () => {
    const registry = new ToolRegistry();
    let requiredProperty = 'city';
    let executorCalls = 0;
    const definition = (): ToolDefinition => ({
      name: 'lookup',
      description: 'Look something up',
      inputSchema: {
        type: 'object',
        properties: {city: {type: 'string'}, zip: {type: 'string'}},
        required: [requiredProperty],
      },
    });
    registry.register(definition, async () => {
      executorCalls += 1;
      return 'ok';
    });

    const first = await registry.execute('lookup', {city: 'Oslo'});
    requiredProperty = 'zip';
    const second = await registry.execute('lookup', {city: 'Oslo'});

    expect({first: first.result, secondNamesZip: second.result.includes('zip'), executorCalls}).toEqual({
      first: 'ok',
      secondNamesZip: true,
      executorCalls: 1,
    });
  });
});
EOF
